<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import {invoke} from '@tauri-apps/api/core'
import Icon from './Icon.vue'
import type {Workspace,Printer,Receipt,UpdateInfo} from './types'
const props=defineProps<{tab:string;view:Workspace;language:string;queues:string[];money:(n:number)=>string;patch:UpdateInfo|null}>()
const emit=defineEmits<{update:[Workspace];error:[unknown];receipt:[Receipt];shift:[boolean];check:[];install:[]}>()
const tr=(id:string,en:string)=>props.language==='id'?id:en
const bindings=ref<Record<string,Printer>>({});const busy=ref(false)
const kitchens=computed(()=>props.view.snapshot?.settings.kitchens??[])
const buckets=computed(()=>props.view.metrics.buckets??Array(12).fill(0));const peak=computed(()=>Math.max(1,...buckets.value))
watch(()=>props.view.kitchen_printers,()=>{bindings.value=JSON.parse(JSON.stringify(props.view.kitchen_printers));for(const k of kitchens.value)bindings.value[k.id]??={transport:'windows',queue:'',host:'',port:9100,paper_mm:58,drawer_enabled:false,auto_print:true}},{immediate:true})
async function save(){busy.value=true;try{emit('update',await invoke<Workspace>('save_kitchen_printers',{settings:bindings.value}))}catch(e){emit('error',e)}finally{busy.value=false}}
async function print(id:string,duplicate:boolean){busy.value=true;try{emit('update',await invoke<Workspace>('print_kitchen',{id,duplicate}))}catch(e){emit('error',e)}finally{busy.value=false}}
</script>
<template>
<main class="page-content enterprise-panels">
<template v-if="tab==='dashboard'">
<div class="dashboard-welcome"><div><span class="eyebrow">{{tr('HARI INI · WIB','TODAY · WIB')}}</span><h2>{{tr('Setiap transaksi, lebih berarti.','Make every transaction count.')}}</h2><p>{{tr('Pantau realisasi penjualan dan kesiapan kasir Anda.','Keep an eye on sales and checkout readiness.')}}</p><button class="secondary" @click="emit('shift',!view.shift)"><Icon name="wallet"/>{{view.shift?tr('Tutup kas & laporan','Close cash & report'):tr('Buka shift kasir','Open cashier shift')}}</button></div><div class="welcome-emblem"><Icon name="store" :size="72"/><span><Icon name="circle-check" :size="25"/></span></div></div>
<div class="metric-grid"><article><span class="metric-icon violet"><Icon name="wallet"/></span><small>{{tr('Penjualan perangkat','Device sales')}}</small><strong>{{money(view.metrics.gross??0)}}</strong><p>{{tr('Semua struk hari ini','All receipts today')}}</p></article><article><span class="metric-icon mint"><Icon name="circle-check"/></span><small>{{tr('Diterima server','Accepted by server')}}</small><strong>{{money(view.metrics.accepted??0)}}</strong><p>{{tr('Transaksi sudah tersinkron','Transactions synchronized')}}</p></article><article><span class="metric-icon amber"><Icon name="receipt-text"/></span><small>{{tr('Jumlah transaksi','Transactions')}}</small><strong>{{view.metrics.count??0}} <em>{{tr('struk','receipts')}}</em></strong><p>{{tr('Tercatat pada perangkat ini','Recorded on this device')}}</p></article><article><span class="metric-icon violet"><Icon name="clock-3"/></span><small>{{tr('Belum diterima server','Awaiting server acceptance')}}</small><strong>{{money(view.metrics.waiting??0)}}</strong><p>{{view.pending}} {{tr('antrean operasi','queued operations')}}</p></article></div>
<div class="dashboard-lower"><section class="chart-card"><div class="panel-heading"><div><h3>{{tr('Aktivitas penjualan','Sales activity')}}</h3><p>{{tr('Realisasi per dua jam · perangkat ini','Sales every two hours · this device')}}</p></div><span class="count-tag">{{view.products[0]?.currency??'IDR'}}</span></div><div class="bar-chart" role="img" :aria-label="tr('Grafik penjualan perangkat hari ini','Device sales chart for today')"><div v-for="(value,i) in buckets" :key="i" class="bar-column"><span class="bar-value">{{value?money(value):''}}</span><div class="bar-track"><i :style="{height:`${Math.max(value?3:0,value/peak*100)}%`}" :title="money(value)"/></div><small>{{String(i*2).padStart(2,'0')}}</small></div></div></section><section class="shift-status"><span class="section-icon mint"><Icon name="shield-check"/></span><h3>{{view.shift?tr('Shift sedang berjalan','Shift in progress'):tr('Siap untuk shift baru','Ready for a new shift')}}</h3><p>{{view.snapshot?.cashier_name}}</p><dl><div><dt>{{tr('Kas pembukaan','Opening cash')}}</dt><dd>{{money(view.shift?.opening??0)}}</dd></div><div><dt>{{tr('Mulai','Started')}}</dt><dd>{{view.shift?new Date(view.shift.opened_at*1000).toLocaleTimeString(): '—'}}</dd></div><div><dt>{{tr('Izin offline tersisa','Offline window remaining')}}</dt><dd>{{Math.max(0,Math.floor(view.lease_remaining/60))}} min</dd></div></dl><p class="field-help">{{tr('Data kasir tersimpan lokal dan akan disinkronkan saat internet tersedia.','Cashier records are stored locally and synchronize when internet is available.')}}</p></section></div>
</template>
<template v-else-if="tab==='shifts'"><div class="page-intro"><div><h2>{{tr('Kas rapi, pergantian shift lancar.','Clear cash records. Smoother handovers.')}}</h2><p>{{tr('Buka kas, catat penutupan, lalu cetak laporan Anda.','Open cash, record closing counts, and print your report.')}}</p></div><button class="primary compact" @click="emit('shift',!view.shift)"><Icon name="wallet"/>{{view.shift?tr('Tutup kas','Close cash'):tr('Buka kas','Open cash')}}</button></div><div class="table-card"><table><thead><tr><th>{{tr('Waktu','Time')}}</th><th>{{tr('Petugas','Cashier')}}</th><th>{{tr('Kas awal','Opening cash')}}</th><th>{{tr('Penjualan','Sales')}}</th><th>{{tr('Kas dihitung','Counted cash')}}</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="o in view.operations.filter(o=>o.operation.kind==='shift_close')" :key="o.operation.operation_id"><td>{{new Date(o.operation.created_at*1000).toLocaleString()}}</td><td>{{o.receipt.cashier}}</td><td>{{money(o.receipt.opening??0)}}</td><td>{{money(o.receipt.sales??0)}}</td><td><strong>{{money(o.receipt.counted??0)}}</strong></td><td><span class="status-chip" :class="o.state">{{o.state==='accepted'?tr('Disahkan','Finalized'):tr('Menunggu pengesahan','Awaiting finalization')}}</span></td><td><button class="text-button" @click="emit('receipt',o)"><Icon name="receipt-text" :size="16"/>{{tr('Laporan','Report')}}</button></td></tr></tbody></table><div v-if="!view.operations.some(o=>o.operation.kind==='shift_close')" class="empty"><Icon name="wallet" :size="38"/><h3>{{tr('Laporan pertama menunggu Anda.','Your first report will appear here.')}}</h3><p>{{tr('Laporan dibuat ketika Anda menutup kas.','Reports are created when you close cash.')}}</p></div></div><div class="help-note"><Icon name="shield-check"/><p>{{tr('Penutupan dicatat lokal. Setelah sinkronisasi, akun berwenang yang berbeda dari pembuka shift mengesahkan penutupan di web. Email mengikuti penerima yang diatur pemilik bisnis.','Closure is recorded locally. After synchronization, an authorized account other than the opener finalizes it on the web. Email recipients are configured by the business owner.')}}</p></div></template>
<template v-else-if="tab==='kitchens'"><div class="page-intro"><div><h2>{{tr('Setiap dapur punya alurnya.','A clear route for every kitchen.')}}</h2><p>{{tr('Kategori diatur melalui web. Hubungkan printer untuk perangkat ini.','Categories are managed on the web. Connect printers for this device.')}}</p></div><button class="primary compact" :disabled="busy||!kitchens.length" @click="save"><Icon name="check"/>{{tr('Simpan printer','Save printers')}}</button></div><div class="kitchen-grid"><section v-for="k in kitchens" :key="k.id" class="settings-card"><div class="panel-heading"><span class="section-icon violet"><Icon name="printer"/></span><span class="count-tag">{{tr('Tiket hemat kertas','Compact tickets')}}</span></div><h3>{{k.name}}</h3><p>{{k.categories.join(' · ')}}</p><template v-if="bindings[k.id]"><label>{{tr('Sambungan','Connection')}}<select v-model="bindings[k.id].transport"><option value="windows">USB / Bluetooth · Windows</option><option value="network">LAN / WLAN · TCP/IP</option></select></label><label v-if="bindings[k.id].transport==='windows'">Printer<select v-model="bindings[k.id].queue"><option value="">{{tr('Pilih printer','Choose printer')}}</option><option v-for="q in queues" :key="q">{{q}}</option></select></label><div v-else class="field-row"><label>Host / IP<input v-model="bindings[k.id].host"/></label><label>Port<input v-model.number="bindings[k.id].port" type="number" min="1" max="65535"/></label></div><label>{{tr('Lebar kertas','Paper width')}}<select v-model.number="bindings[k.id].paper_mm"><option :value="58">58 mm</option><option :value="80">80 mm</option></select></label><label class="check-label"><input type="checkbox" v-model="bindings[k.id].auto_print"/>{{tr('Cetak otomatis setelah pembayaran','Print automatically after payment')}}</label></template></section></div><div v-if="!kitchens.length" class="empty"><Icon name="printer" :size="40"/><h3>{{tr('Dapur belum dikonfigurasi.','No kitchens configured yet.')}}</h3><p>{{tr('Tambahkan dapur dan kategori pada Pengaturan POS Windows di web.','Add kitchens and categories in Windows POS Settings on the web.')}}</p></div><div class="table-card"><table><thead><tr><th>{{tr('Dapur','Kitchen')}}</th><th>{{tr('Referensi','Reference')}}</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="j in view.kitchen_jobs" :key="j.id"><td>{{kitchens.find(k=>k.id===j.kitchen_id)?.name??j.kitchen_id}}</td><td class="reference">{{j.operation_id.slice(-12)}}</td><td>{{j.state}}</td><td><button class="text-button" :disabled="busy||j.state==='printing'" @click="print(j.id,j.state!=='queued')">{{j.state==='queued'?tr('Cetak','Print'):tr('Cetak salinan','Print copy')}}</button></td></tr></tbody></table></div></template>
<template v-else-if="tab==='updates'"><div class="update-hero"><span class="update-icon"><Icon name="refresh-cw" :size="48"/></span><span class="eyebrow">ONEQAY POS · WINDOWS</span><h2>{{patch?.available?tr('Pembaruan siap untuk Anda.','An update is ready for you.'):tr('Selalu siap dengan versi terbaru.','Stay ready with the latest version.')}}</h2><p>{{tr('Pembaruan diperiksa otomatis saat aplikasi aktif. Anda menentukan waktu pemasangannya.','Updates are checked automatically while the app is running. You choose when to install.')}}</p><span class="version-pill">v{{patch?.current??'0.2.0'}} <template v-if="patch?.available">→ v{{patch.version}}</template></span><pre v-if="patch?.notes">{{patch.notes}}</pre><div class="button-row"><button class="secondary" @click="emit('check')">{{tr('Periksa pembaruan','Check for updates')}}</button><button v-if="patch?.available" class="primary compact" :disabled="!!view.shift||view.pending>0||view.review>0" @click="emit('install')"><Icon name="refresh-cw"/>{{tr('Pasang & mulai ulang','Install & restart')}}</button></div><div class="update-steps"><div><Icon name="shield-check"/><b>{{tr('Tanda tangan diverifikasi','Signature verified')}}</b><span>{{tr('Hanya patch resmi oneQay','Official oneQay patches only')}}</span></div><div><Icon name="database"/><b>{{tr('Cadangan sebelum update','Backup before updating')}}</b><span>{{tr('Data lokal tetap tersimpan','Local records are preserved')}}</span></div><div><Icon name="circle-check"/><b>{{tr('Menunggu kas selesai','Waits until cash is closed')}}</b><span>{{tr('Selesaikan sinkronisasi & tinjauan','Complete synchronization & review')}}</span></div></div></div></template>
</main>
</template>
